        ),
        (
            "{x: y for (x, y) in zip(range(5), range(5))}",
            [
                "./example.py:1:1: C416 Unnecessary dict comprehension - "
                + "rewrite using dict().",
            ],
        ),
        (
            "[x for x in range(5)]",
            [
                "./example.py:1:1: C416 Unnecessary "
                + "list comprehension - rewrite using list()."
            ],
        ),
        (
            "{x for x in range(5)}",
